BEGIN;
CREATE TABLE IF NOT EXISTS knowledge_sources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid REFERENCES organizations(id),authority_class text NOT NULL,jurisdiction text,title text NOT NULL,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS knowledge_source_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_id uuid NOT NULL REFERENCES knowledge_sources(id),version_label text NOT NULL,checksum_sha256 text NOT NULL,parser_version text,effective_from date,superseded_at timestamptz,object_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(source_id,checksum_sha256));
CREATE TABLE IF NOT EXISTS knowledge_blocks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_version_id uuid NOT NULL REFERENCES knowledge_source_versions(id),page_no integer,block_no integer NOT NULL,text_content text NOT NULL,coordinates jsonb,extraction_confidence numeric(5,4),UNIQUE(source_version_id,block_no));
CREATE TABLE IF NOT EXISTS citations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_version_id uuid NOT NULL REFERENCES knowledge_source_versions(id),block_id uuid NOT NULL REFERENCES knowledge_blocks(id),page_no integer,locator jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS ai_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),task_type text NOT NULL,provider text NOT NULL,model text NOT NULL,status text NOT NULL,prompt_version text,retrieval_snapshot jsonb,output_schema_version text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workflows(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),workflow_key text NOT NULL,definition_version text NOT NULL,state text NOT NULL,digest text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workflow_checkpoints(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workflow_id uuid NOT NULL REFERENCES workflows(id),sequence_no bigint NOT NULL,digest text NOT NULL,state_json jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workflow_id,sequence_no));
CREATE TABLE IF NOT EXISTS signed_approvals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workflow_id uuid NOT NULL REFERENCES workflows(id),checkpoint_id uuid NOT NULL REFERENCES workflow_checkpoints(id),approver_id uuid NOT NULL REFERENCES users(id),approval_key text NOT NULL,workflow_digest text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
COMMIT;
